function initials(name = 'FitSync') {
  return name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase();
}

function Avatar({ name, className = '' }: { name?: string; className?: string }) {
  return <div data-testid={`avatar-${name ?? 'user'}`} className={`grid size-9 shrink-0 place-items-center rounded-full bg-teal-100 text-xs font-bold text-teal-800 ${className}`}>{initials(name)}</div>;
}

function Button({ children, className = '', variant = 'primary', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'ghost' | 'danger' }) {
  const styles = {
    primary: 'bg-primary text-primary-foreground hover:brightness-95 shadow-[0_4px_0_hsl(35_95%_44%)]',
    secondary: 'border border-border bg-card text-foreground hover:bg-muted',
    ghost: 'text-muted-foreground hover:bg-muted hover:text-foreground',
    danger: 'bg-destructive text-destructive-foreground hover:brightness-95',
  };
  return <button {...props} className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-bold ${styles[variant]} ${className}`}>{children}</button>;
}

function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'green' | 'orange' | 'red' | 'teal' }) {
  const tones = { neutral: 'bg-muted text-muted-foreground', green: 'bg-emerald-100 text-emerald-800', orange: 'bg-orange-100 text-orange-800', red: 'bg-red-100 text-red-700', teal: 'bg-teal-100 text-teal-800' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold ${tones[tone]}`}>{children}</span>;
}

function LoadingBlock({ rows = 4 }: { rows?: number }) {
  return <div className="space-y-3" data-testid="loading-content">{Array.from({ length: rows }).map((_, i) => <div key={i} className="skeleton h-14 rounded-xl bg-muted" />)}</div>;
}

function ErrorBlock({ message = 'We could not load this view.', retry }: { message?: string; retry?: () => void }) {
  return <div className="rounded-2xl border border-red-200 bg-red-50 p-6 text-red-800" data-testid="error-message"><p className="font-bold">{message}</p><p className="mt-1 text-sm text-red-700">Try again or check your connection.</p>{retry && <Button onClick={retry} variant="secondary" className="mt-4 border-red-200">Retry</Button>}</div>;
}

function EmptyBlock({ icon: Icon = Sparkles, title, detail, action }: { icon?: typeof Sparkles; title: string; detail: string; action?: ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-border bg-card p-10 text-center" data-testid="empty-state"><Icon className="mx-auto size-9 text-primary" /><h3 className="mt-4 display-font text-lg font-bold">{title}</h3><p className="mx-auto mt-1 max-w-sm text-sm text-muted-foreground">{detail}</p>{action && <div className="mt-5">{action}</div>}</div>;
}

