function Login() {
  const [, setLocation] = useLocation();
  const login = useLogin();
  const demos = useGetDemoAccounts({ query: { queryKey: getGetDemoAccountsQueryKey() } });
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState('');
  const submit = (event: FormEvent) => { event.preventDefault(); setError(''); if (!email || !email.includes('@')) return setError('Enter a valid email address.'); if (password.length < 4) return setError('Password must be at least 4 characters.'); login.mutate({ data: { email, password } }, { onSuccess: (session) => { localStorage.setItem('fitsync_token', session.token); localStorage.setItem('fitsync_user', JSON.stringify(session.user)); window.dispatchEvent(new Event('fitsync-auth')); setLocation('/dashboard'); }, onError: () => setError('Those details did not work. Choose a demo account to explore FitSync.') }); };
  const chooseDemo = (account: DemoAccount) => { setEmail(account.email); setPassword(account.password); };
  return <div className="noise grid min-h-[100dvh] bg-background lg:grid-cols-[.9fr_1.1fr]"><aside className="relative hidden overflow-hidden bg-sidebar p-10 text-sidebar-foreground lg:flex lg:flex-col lg:justify-between"><div><Brand dark /><div className="mt-28 max-w-md"><Badge tone="orange">WELCOME BACK</Badge><h1 className="display-font mt-6 text-5xl font-bold leading-[1.02] tracking-[-.05em]">Good systems make room for <span className="text-primary">great coaching.</span></h1><p className="mt-6 leading-7 text-sidebar-foreground/65">Pick up where your team left off. Your gym, your people, one clear rhythm.</p></div></div><div className="flex items-center gap-3 text-sm text-sidebar-foreground/55"><ShieldCheck className="size-4 text-primary" />Secure, role-aware access for every gym</div></aside><main className="flex items-center justify-center p-5 sm:p-10"><div className="w-full max-w-md animate-rise"><div className="lg:hidden"><Brand /></div><div className="mt-10 lg:mt-0"><p className="text-sm font-bold uppercase tracking-[.18em] text-accent">Sign in</p><h2 className="display-font mt-3 text-4xl font-bold tracking-tight">Welcome to your gym.</h2><p className="mt-3 text-muted-foreground">Use your FitSync credentials to continue.</p></div><form onSubmit={submit} className="mt-8 space-y-4"><label className="block text-sm font-bold">Email<input data-testid="input-email" value={email} onChange={(e) => setEmail(e.target.value)} type="email" placeholder="you@yourgym.com" className="mt-2 h-12 w-full rounded-xl border border-input bg-card px-4 outline-none focus:ring-2 focus:ring-primary" /></label><label className="block text-sm font-bold">Password<input data-testid="input-password" value={password} onChange={(e) => setPassword(e.target.value)} type="password" placeholder="••••••••" className="mt-2 h-12 w-full rounded-xl border border-input bg-card px-4 outline-none focus:ring-2 focus:ring-primary" /></label>{error && <p className="rounded-xl bg-red-50 p-3 text-sm font-semibold text-red-700" data-testid="login-error">{error}</p>}<Button type="submit" disabled={login.isPending} className="w-full">{login.isPending ? 'Signing you in…' : 'Sign in'} <ArrowRight className="size-4" /></Button></form><div className="my-8 flex items-center gap-3 text-xs font-bold uppercase tracking-widest text-muted-foreground"><span className="h-px flex-1 bg-border" />Demo access<span className="h-px flex-1 bg-border" /></div><div className="grid gap-2">{demos.isLoading ? <LoadingBlock rows={4} /> : demos.isError ? <ErrorBlock message="Demo accounts are temporarily unavailable." retry={() => demos.refetch()} /> : (demos.data ?? []).map((account) => <button data-testid={`button-demo-${account.role}`} key={account.role} onClick={() => chooseDemo(account)} className="flex items-center justify-between rounded-xl border border-border bg-card p-3 text-left hover:border-primary"><span className="flex items-center gap-3"><Avatar name={account.name} /><span><span className="block text-sm font-bold">{account.name}</span><span className="block text-xs capitalize text-muted-foreground">{account.role.replace('_', ' ')}</span></span></span><ChevronRight className="size-4 text-muted-foreground" /></button>)}</div><p className="mt-8 text-center text-sm text-muted-foreground">New to FitSync? <Link href="/" data-testid="link-back-home" className="font-bold text-foreground underline decoration-primary decoration-2 underline-offset-4">See how it works</Link></p></div></main></div>;
}

function useAuth() {
  const [user, setUser] = useState<AuthUser | null>(() => { try { const raw = localStorage.getItem('fitsync_user'); return raw ? JSON.parse(raw) : null; } catch { return null; } });
  useEffect(() => {
    const sync = () => { try { const raw = localStorage.getItem('fitsync_user'); setUser(raw ? JSON.parse(raw) : null); } catch { setUser(null); } };
    window.addEventListener('fitsync-auth', sync);
    return () => window.removeEventListener('fitsync-auth', sync);
  }, []);
  const logout = () => { localStorage.removeItem('fitsync_token'); localStorage.removeItem('fitsync_user'); setUser(null); };
  return { user, setUser, logout, token: typeof window !== 'undefined' ? localStorage.getItem('fitsync_token') : null };
}

